--- Return the full route data table for a key, or nil.
---@param routeKey string
---@return table|nil routeData
function APR:GetRouteData(routeKey)
    if not routeKey then return nil end
    local routeData = self.RouteQuestStepList[routeKey]
    if type(routeData) ~= "table" then return nil end
    if not self:IsRouteCompatibleWithClient(routeData) then return nil end
    return routeData
end--[[APR_DIAG]]; APR.GetRouteData = APRTrace("APR-Core/features/questing/RouteManager.lua:44:APR:GetRouteData#4", APR.GetRouteData)--[[/APR_DIAG]]

--- Packaging selects built-in route files. This also protects unpackaged checkouts
--- and saved custom routes copied between clients, before soft visibility filters.
function APR:IsRouteCompatibleWithClient(routeData)
    local gameVersion = routeData.gameVersion
    if not gameVersion and routeData.expansion then
        if routeData.expansion == self.EXPANSIONS.Forever then
            gameVersion = APR.GAME_VERSIONS.Forever
        elseif routeData.expansion ~= self.EXPANSIONS.Custom then
            gameVersion = APR.GAME_VERSIONS.Retail
        end
    end
    return not gameVersion or gameVersion == self:GetGameVersion()
end--[[APR_DIAG]]; APR.IsRouteCompatibleWithClient = APRTrace("APR-Core/features/questing/RouteManager.lua:54:APR:IsRouteCompatibleWithClient#5", APR.IsRouteCompatibleWithClient)--[[/APR_DIAG]]

--- Only create expansion tabs supported by this client, including empty tabs.
function APR:GetRouteSelectionExpansions()
    local expansions = {}
    for _, key in ipairs(self.EXPANSION_ORDER_KEYS or {}) do
        local expansion = self.EXPANSIONS[key]
        if expansion and self:IsRouteCompatibleWithClient({ expansion = expansion }) then
            table.insert(expansions, expansion)
        end
    end
    return expansions
end--[[APR_DIAG]]; APR.GetRouteSelectionExpansions = APRTrace("APR-Core/features/questing/RouteManager.lua:67:APR:GetRouteSelectionExpansions#6", APR.GetRouteSelectionExpansions)--[[/APR_DIAG]]

local scenarioStepsCache = setmetatable({}, { __mode = "k" })
local function FlattenScenarioBlocks(blocks, scenarioID)
    local variants = blocks and scenarioStepsCache[blocks]
    local cached = variants and (scenarioID and variants.selected or variants.all)
    if cached and cached.scenarioID == scenarioID then
        local count, unchanged = 0, true
        for _, block in ipairs(blocks) do
            if not scenarioID or tonumber(block.scenarioID) == tonumber(scenarioID) then
                for _, step in ipairs(block.steps or {}) do
                    count = count + 1
                    if cached.steps[count] ~= step then unchanged = false; break end
                end
            end
            if not unchanged then break end
        end
        if unchanged and count == #cached.steps then return cached.steps end
    end
    local steps = {}
    for _, block in ipairs(blocks or {}) do
        if not scenarioID or tonumber(block.scenarioID) == tonumber(scenarioID) then
            for _, step in ipairs(block.steps or {}) do
                table.insert(steps, step)
            end
        end
    end
    if blocks then
        variants = variants or {}
        local snapshot = { scenarioID = scenarioID, steps = steps }
        if scenarioID then variants.selected = snapshot else variants.all = snapshot end
        scenarioStepsCache[blocks] = variants
    end
    return steps
end--[[APR_DIAG]]; FlattenScenarioBlocks = APRTrace("APR-Core/features/questing/RouteManager.lua:79:FlattenScenarioBlocks#7", FlattenScenarioBlocks)--[[/APR_DIAG]]

local function GetActiveDelveScenarioID(routeKey)
